                                    $items6[$xid][$xid6]['jml'] = $itemsKomposisi[$xid][$id]["jml"] * $validItems[$xid];
                                    $items6[$xid][$xid6]['qty'] = $itemsKomposisi[$xid][$id]["jml"] * $validItems[$xid];
                                    $items6[$xid][$xid6]['max_jml'] = $items6[$xid][$xid6]['qty'];
